function header() {
  return `<header class="site-header"><div class="header-inner"><a class="brand" href="index.html" aria-label="${t.homeAria}"><img src="assets/logo.jpg" alt="HolidayTime"></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="main-nav"><span></span><span></span><span></span><span class="sr-only">${t.menu}</span></button><nav class="main-nav" id="main-nav" aria-label="${t.menu}">${navItems.map(([key, label, href]) => `<a href="${href}"${page === key || (page === "house" && key === "booking") ? ' aria-current="page"' : ""}>${label}</a>`).join("")}</nav><button class="language" type="button" aria-label="${t.switchLanguage}"><span class="globe" aria-hidden="true"><i></i><b></b></span><span>${language === "uk" ? "UA" : "EN"}</span></button></div></header>`;
}
function footer() { return `<footer class="site-footer"><p>${t.footer}</p></footer>`; }
function titlebar(title) { return `<div class="titlebar"><div>${title}</div></div>`; }
function topButton() { return `<button class="to-top" type="button" aria-label="${t.backToTop}"><span aria-hidden="true">↑</span></button>`; }

function home() {
  const slides = t.home.slides.map(([image, text, alt], index) => `<article class="feature-slide${index === 0 ? " is-active" : ""}" data-slide="${index}" aria-hidden="${index !== 0}"><img src="${image}" alt="${alt}"><div class="featured-copy"><p>${text}</p></div><a class="detail-pill" href="${index === 0 ? "house.html" : "booking.html"}">${t.home.view}<span aria-hidden="true">→</span></a></article>`).join("");
  return `${header()}<main class="home-page"><section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><h1 id="hero-title">HolidayTime</h1><p>${t.home.hero}</p></div></section><section class="featured-place" aria-roledescription="carousel" aria-label="HolidayTime"><div class="slider-track">${slides}</div><button class="slider-arrow slider-prev" type="button" aria-label="${t.home.previousSlide}"><span aria-hidden="true"></span></button><button class="slider-arrow slider-next" type="button" aria-label="${t.home.nextSlide}"><span aria-hidden="true"></span></button><div class="slider-dots">${t.home.slides.map((_, index) => `<button type="button" data-slide-dot="${index}" class="${index === 0 ? "is-active" : ""}" aria-label="${t.home.goToSlide} ${index + 1}" aria-current="${index === 0}"></button>`).join("")}</div></section><section class="activity-card"><img src="assets/couple.png" alt=""><p>${t.home.activity}</p></section><form class="feedback-card" data-success="${t.home.sent}"><h2>${t.home.feedback}</h2><label for="feedback-name">${t.home.name}</label><input id="feedback-name" name="name" autocomplete="name" placeholder="${t.home.namePlaceholder}" required><label for="feedback-phone">${t.home.phone}</label><input id="feedback-phone" name="phone" type="tel" autocomplete="tel" placeholder="${t.home.phonePlaceholder}" required><button type="submit">${t.home.call}</button></form></main>${topButton()}${footer()}`;
}
function about() { return `${header()}${titlebar(t.about.title)}<main class="about-page"><section class="about-banner"><img src="assets/about-nature.png" alt=""><div><h1>HolidayTime</h1><p>${t.about.tagline}</p></div></section><section class="about-copy">${t.about.paragraphs.map((paragraph) => `<p>${paragraph}</p>`).join("")}</section></main>${footer()}`; }
function booking() { return `${header()}${titlebar(t.booking.title)}<main class="booking-page"><div class="location-select"><button class="location-trigger" type="button" aria-haspopup="listbox" aria-expanded="false"><span>${t.booking.choose}</span><i aria-hidden="true"></i></button><div class="location-menu" role="listbox" hidden>${t.booking.locations.map(([value, label]) => `<button type="button" role="option" data-location-option="${value}" aria-selected="false">${label}</button>`).join("")}</div></div><div class="stay-list">${stays.map((stay) => `<article class="stay-card" data-location="${stay.location}"><img src="${stay.image}" alt="${stay.title}"><div class="stay-info"><h2>${stay.title}</h2><span class="stay-rule"></span><button class="favorite" type="button" aria-label="${t.booking.addFavorite}: ${stay.title}" aria-pressed="false">★</button><p>${stay.text}</p><a href="house.html">${t.booking.details}</a></div></article>`).join("")}</div></main>${topButton()}${footer()}`; }

const peopleIcon = `<svg viewBox="0 0 92 54" aria-hidden="true"><g fill="currentColor"><circle cx="27" cy="14" r="11"/><path d="M7 51c0-16 8-25 20-25s20 9 20 25H7Z"/><circle cx="66" cy="14" r="11"/><path d="M46 51c0-16 8-25 20-25s20 9 20 25H46Z"/></g></svg>`;
const bedIcon = `<svg viewBox="0 0 98 52" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"><path d="M8 43V18m82 25V28c0-8-6-14-14-14H42c-8 0-14 6-14 14v15M8 30h82M17 30V14h20c7 0 11 5 11 12v4"/><path d="M8 43h82"/></g></svg>`;
function house() { return `${header()}${titlebar(t.house.title)}<main class="house-page"><a class="back-link" href="booking.html"><span aria-hidden="true">←</span>${t.house.back}</a><section class="house-overview"><div class="house-left"><img src="assets/cabin.png" alt=""><img src="assets/cabin-interior-3.png" alt=""></div><div class="house-right"><div class="house-description"><p>${t.house.description1}</p><p>${t.house.description2}</p></div><div class="house-gallery"><img src="assets/cabin-interior-1.png" alt=""><img src="assets/cabin-interior-2.png" alt=""></div></div></section><h1 class="availability-title">${t.house.availability}</h1><form class="availability-form" data-success="${t.house.found}"><p>${t.house.question}</p><div class="availability-row"><div class="date-field"><label for="checkin">${t.house.checkin}</label><input id="checkin" name="checkin" type="date" required></div><div class="date-field"><label for="checkout">${t.house.checkout}</label><input id="checkout" name="checkout" type="date" required></div><button class="availability-submit" type="submit">${t.house.check}</button></div><div class="count-row"><label class="count-field"><span>${t.house.rooms}</span><select name="rooms"><option>1</option><option>2</option><option>3</option></select></label><label class="count-field"><span>${t.house.adults}</span><select name="adults"><option>2</option><option>1</option><option>3</option><option>4</option></select></label><label class="count-field"><span>${t.house.children}</span><select name="children"><option>0</option><option>1</option><option>2</option></select></label></div></form><section class="room-table" aria-label="${t.house.availability}"><div class="room-head"><span>${t.house.fits}</span><span>${t.house.accommodation}</span><span>${t.house.price}</span></div><div class="room-row"><span class="guests">${peopleIcon}</span><span class="room-description"><b>${t.house.doubleRoom}</b><small>${t.house.doubleBed}${bedIcon}</small></span><a href="#" data-book>${t.house.showPrices}</a></div></section></main>${topButton()}${footer()}`; }
function contacts() { return `${header()}${titlebar(t.contacts.title)}<main class="contacts-page"><section class="contact-grid"><div><h2>${t.contacts.phone}</h2><a href="tel:+380971198983">+38(097)119-89-83</a></div><div><h2>${t.contacts.hours}</h2><p>${t.contacts.schedule}</p></div><div><h2>${t.contacts.email}</h2><a href="mailto:hello@gmail.com">hello@gmail.com</a></div><div><h2>${t.contacts.office}</h2><p>${t.contacts.address}</p></div><a class="map" href="https://maps.google.com/?q=Київ,+вул.+Малевича,+4" target="_blank" rel="noreferrer" aria-label="${t.contacts.openMap}"><img src="assets/map.png" alt=""></a></section></main>${footer()}`; }

function getProfile() {
  const defaults = { name: language === "uk" ? "Петров Іван Іванович" : "Ivan Petrov", gender: t.account.male, birthday: "10. 02. 1998", phone: "+38(097)346-72-50", email: "petrov@gmail.com" };
  try { return { ...defaults, ...JSON.parse(readStorage("holidaytimeProfile", "{}")) }; } catch { return defaults; }
}
function authPanel() { return `<section class="auth-card"><div class="auth-tabs" role="tablist"><button class="is-active" type="button" role="tab" aria-selected="true" data-auth-tab="login">${t.account.login}</button><button type="button" role="tab" aria-selected="false" data-auth-tab="register">${t.account.register}</button></div><p class="auth-hint">${t.account.authHint}</p><form class="auth-form is-active" data-auth-form="login"><label>${t.account.emailField}<input type="email" name="email" autocomplete="email" required></label><label>${t.account.password}<input type="password" name="password" autocomplete="current-password" minlength="6" required></label><button type="submit">${t.account.signIn}</button><p>${t.account.noAccount} <button type="button" data-auth-link="register">${t.account.register}</button></p></form><form class="auth-form" data-auth-form="register"><label>${t.account.name}<input name="name" autocomplete="name" required></label><label>${t.account.emailField}<input type="email" name="email" autocomplete="email" required></label><label>${t.account.password}<input type="password" name="password" autocomplete="new-password" minlength="6" required></label><label>${t.account.confirmPassword}<input type="password" name="confirm" autocomplete="new-password" minlength="6" required></label><button type="submit">${t.account.createAccount}</button><p>${t.account.hasAccount} <button type="button" data-auth-link="login">${t.account.login}</button></p></form></section>`; }
function account() {
  const signedOut = readStorage("holidaytimeAuth", "signedIn") === "signedOut";
  if (signedOut) return `${header()}${titlebar(t.account.title)}<main class="account-page signed-out">${authPanel()}</main>${footer()}`;
  const profile = getProfile();
  const avatar = readStorage("holidaytimeAvatar", "assets/profile.png");
  return `${header()}${titlebar(t.account.title)}<main class="account-page"><section class="profile-card"><div class="profile-actions"><div class="avatar-frame"><img src="${avatar}" alt=""></div><input class="sr-only" id="avatar-input" type="file" accept="image/png,image/jpeg,image/webp"><button class="change-avatar" type="button" data-avatar>${t.account.changeAvatar}</button><button class="settings" type="button" data-settings>${t.account.settings}</button></div><dl><div><dt class="sr-only">${t.account.name}</dt><dd><strong data-profile-name>${profile.name}</strong></dd></div><div><dt>${t.account.gender}</dt><dd data-profile-gender>${profile.gender}</dd></div><div><dt>${t.account.birthday}</dt><dd data-profile-birthday>${profile.birthday}</dd></div><div><dt>${t.account.mobile}</dt><dd data-profile-phone>${profile.phone}</dd></div><div><dt>${t.account.email}</dt><dd data-profile-email>${profile.email}</dd></div></dl></section><button class="logout" type="button">${t.account.logout}</button><dialog class="settings-dialog"><form method="dialog" class="settings-form"><div class="dialog-heading"><h2>${t.account.editProfile}</h2><button value="cancel" aria-label="${t.account.close}">×</button></div><label>${t.account.name}<input name="name" value="${profile.name}" required></label><label>${t.account.gender}<input name="gender" value="${profile.gender}" required></label><label>${t.account.birthday}<input name="birthday" value="${profile.birthday}" required></label><label>${t.account.mobile}<input name="phone" value="${profile.phone}" required></label><label>${t.account.email}<input name="email" type="email" value="${profile.email}" required></label><div><button value="cancel">${t.account.cancel}</button><button class="save-profile" value="save">${t.account.save}</button></div></form></dialog></main>${footer()}`;
}

const renderers = { home, about, booking, house, contacts, account };
app.innerHTML = (renderers[page] || home)();
document.documentElement.lang = language;
const titles = { home: "HolidayTime", about: t.about.title, booking: t.booking.title, house: t.house.title, contacts: t.contacts.title, account: t.account.title };
document.title = `HolidayTime — ${titles[page] || titles.home}`;

const menuButton = document.querySelector(".menu-toggle");
menuButton?.addEventListener("click", () => { const isOpen = document.body.classList.toggle("menu-open"); menuButton.setAttribute("aria-expanded", String(isOpen)); });
document.querySelector(".language")?.addEventListener("click", () => { writeStorage("holidaytimeLanguage", language === "uk" ? "en" : "uk"); window.location.reload(); });
document.querySelector(".to-top")?.addEventListener("click", () => window.scrollTo({ top: 0, behavior: "smooth" }));
document.querySelectorAll("form[data-success]").forEach((form) => form.addEventListener("submit", (event) => { event.preventDefault(); if (!form.reportValidity()) return; showToast(form.dataset.success); }));
document.querySelectorAll(".favorite").forEach((button) => button.addEventListener("click", () => { const active = button.getAttribute("aria-pressed") === "true"; button.setAttribute("aria-pressed", String(!active)); button.classList.toggle("is-favorite", !active); const title = button.closest(".stay-card")?.querySelector("h2")?.textContent || ""; button.setAttribute("aria-label", `${active ? t.booking.addFavorite : t.booking.removeFavorite}: ${title}`); }));

const locationTrigger = document.querySelector(".location-trigger");
const locationMenu = document.querySelector(".location-menu");
function setLocationMenu(open) { if (!locationTrigger || !locationMenu) return; locationTrigger.setAttribute("aria-expanded", String(open)); locationMenu.hidden = !open; document.querySelector(".location-select")?.classList.toggle("is-open", open); }
locationTrigger?.addEventListener("click", () => setLocationMenu(locationTrigger.getAttribute("aria-expanded") !== "true"));
document.querySelectorAll("[data-location-option]").forEach((option) => option.addEventListener("click", () => { const value = option.dataset.locationOption; locationTrigger.querySelector("span").textContent = option.textContent; document.querySelectorAll("[data-location-option]").forEach((item) => item.setAttribute("aria-selected", String(item === option))); document.querySelectorAll(".stay-card").forEach((card) => { card.hidden = card.dataset.location !== value; }); setLocationMenu(false); }));
document.addEventListener("click", (event) => { if (locationMenu && !event.target.closest(".location-select")) setLocationMenu(false); });
document.addEventListener("keydown", (event) => { if (event.key === "Escape") setLocationMenu(false); });

const slider = document.querySelector(".featured-place");
if (slider) {
  const slides = [...slider.querySelectorAll(".feature-slide")]; const dots = [...slider.querySelectorAll("[data-slide-dot]")]; const previous = slider.querySelector(".slider-prev"); const next = slider.querySelector(".slider-next"); let activeSlide = 0; let timer;
  const showSlide = (index) => { activeSlide = (index + slides.length) % slides.length; slides.forEach((slide, slideIndex) => { const active = slideIndex === activeSlide; slide.classList.toggle("is-active", active); slide.setAttribute("aria-hidden", String(!active)); }); dots.forEach((dot, dotIndex) => { const active = dotIndex === activeSlide; dot.classList.toggle("is-active", active); dot.setAttribute("aria-current", String(active)); }); };
  const startAutoPlay = () => { clearInterval(timer); timer = setInterval(() => showSlide(activeSlide + 1), 6500); };
  previous.addEventListener("click", () => { showSlide(activeSlide - 1); startAutoPlay(); }); next.addEventListener("click", () => { showSlide(activeSlide + 1); startAutoPlay(); }); dots.forEach((dot) => dot.addEventListener("click", () => { showSlide(Number(dot.dataset.slideDot)); startAutoPlay(); })); slider.addEventListener("mouseenter", () => clearInterval(timer)); slider.addEventListener("mouseleave", startAutoPlay); slider.addEventListener("focusin", () => clearInterval(timer)); slider.addEventListener("focusout", startAutoPlay); startAutoPlay();
}

document.querySelector("[data-book]")?.addEventListener("click", (event) => { event.preventDefault(); showToast(t.house.chooseDates); document.querySelector("#checkin")?.focus(); });
function switchAuthPanel(target) { document.querySelectorAll("[data-auth-tab]").forEach((button) => { const active = button.dataset.authTab === target; button.classList.toggle("is-active", active); button.setAttribute("aria-selected", String(active)); }); document.querySelectorAll("[data-auth-form]").forEach((form) => form.classList.toggle("is-active", form.dataset.authForm === target)); }
document.querySelectorAll("[data-auth-tab], [data-auth-link]").forEach((button) => button.addEventListener("click", () => switchAuthPanel(button.dataset.authTab || button.dataset.authLink)));
document.querySelector('[data-auth-form="login"]')?.addEventListener("submit", (event) => { event.preventDefault(); if (!event.currentTarget.reportValidity()) return; writeStorage("holidaytimeAuth", "signedIn"); window.location.reload(); });
document.querySelector('[data-auth-form="register"]')?.addEventListener("submit", (event) => { event.preventDefault(); const form = event.currentTarget; if (!form.reportValidity()) return; const data = new FormData(form); if (data.get("password") !== data.get("confirm")) { showToast(t.account.passwordMismatch); form.elements.confirm.focus(); return; } const profile = getProfile(); profile.name = data.get("name"); profile.email = data.get("email"); writeStorage("holidaytimeProfile", JSON.stringify(profile)); writeStorage("holidaytimeAuth", "signedIn"); window.location.reload(); });
document.querySelector(".logout")?.addEventListener("click", () => { writeStorage("holidaytimeAuth", "signedOut"); window.location.reload(); });

const avatarInput = document.querySelector("#avatar-input");
document.querySelector("[data-avatar]")?.addEventListener("click", () => avatarInput?.click());
avatarInput?.addEventListener("change", () => { const file = avatarInput.files?.[0]; if (!file) return; const reader = new FileReader(); reader.addEventListener("load", () => { writeStorage("holidaytimeAvatar", reader.result); const avatar = document.querySelector(".avatar-frame img"); if (avatar) avatar.src = reader.result; showToast(t.account.avatarUpdated); }); reader.readAsDataURL(file); });
const settingsDialog = document.querySelector(".settings-dialog");
document.querySelector("[data-settings]")?.addEventListener("click", () => settingsDialog?.showModal());
document.querySelector(".save-profile")?.addEventListener("click", (event) => { const form = event.target.closest("form"); if (!form.reportValidity()) { event.preventDefault(); return; } const data = Object.fromEntries(new FormData(form)); writeStorage("holidaytimeProfile", JSON.stringify(data)); ["name", "gender", "birthday", "phone", "email"].forEach((key) => { const node = document.querySelector(`[data-profile-${key}]`); if (node) node.textContent = data[key]; }); showToast(t.account.profileUpdated); });

function showToast(message) {
  document.querySelector(".toast")?.remove(); const toast = document.createElement("div"); toast.className = "toast"; toast.setAttribute("role", "status"); toast.textContent = message; document.body.append(toast); requestAnimationFrame(() => toast.classList.add("show")); setTimeout(() => { toast.classList.remove("show"); setTimeout(() => toast.remove(), 250); }, 3200);
}
